<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import type {PurchaseRequest,Row} from '../api/types'
import {post} from '../api/http'
import {useMediaQuery} from '../composables/useMediaQuery'
import {useAuth} from '../stores/auth'
import {useResource,useMutation,money,number,dateTime,confirmAction,today} from '../composables/useResource'
import PageHeader from '../components/PageHeader.vue'
import ResourceState from '../components/ResourceState.vue'
import StatusTag from '../components/StatusTag.vue'
import DataTable from '../components/DataTable.vue'
import RequestEditor from '../components/RequestEditor.vue'
import RecordSelect from '../components/RecordSelect.vue'
import RelatedRecords from '../components/RelatedRecords.vue'
import {usePagedResource} from '../composables/usePagedResource'
import TracePanel from '../components/TracePanel.vue'
const route=useRoute(),router=useRouter(),auth=useAuth()
const {data,loading,error,load}=useResource<PurchaseRequest|null>(()=>`/requests/${route.params.id}`,null)
const quoteList=usePagedResource(()=>auth.can('quote:read')?`/records/quotes?request_id=${route.params.id}&id=${route.query.quote_id||''}`:'')
async function reload(){await Promise.all([load(),quoteList.load()])}
const {saving,run}=useMutation(reload),tab=ref(String(route.query.tab||'items')),editor=ref(false),quoteDialog=ref(false),awardDialog=ref(false),approvalDialog=ref(false)
const quote=reactive<{supplier_id:any;delivery_days:number;valid_until:string;note:string;items:{request_item_id:any;unit_price:string}[]}>({supplier_id:'',delivery_days:7,valid_until:today(),note:'',items:[]})
const award=reactive({quote_id:'' as string|number,reason:''}),approval=reactive({decision:'APPROVED',comment:''})
const canEdit=computed(()=>auth.can('request:write')&&['DRAFT','REJECTED'].includes(data.value?.status||'')&&(auth.user?.role!=='manager'||String(auth.user.id)===String(data.value?.applicant_id)))
const canApprove=computed(()=>auth.can('request:approve')&&['PENDING','SUBMITTED'].includes(data.value?.status||'')&&String(auth.user?.id)!==String(data.value?.applicant_id))
const quotes=computed<Row[]>(()=>quoteList.data.value)
// Actual request detail keeps APPROVED after award; quotes[].selected is set atomically with the order.
const hasOrder=computed(()=>Boolean(data.value?.has_order))
const canQuote=computed(()=>auth.can('quote:read')&&auth.can('quote:write')&&data.value?.status==='APPROVED'&&!hasOrder.value)
const canAward=computed(()=>auth.can('order:write')&&data.value?.status==='APPROVED'&&!hasOrder.value)
function newQuote(){if(!canQuote.value)return;Object.assign(quote,{supplier_id:'',delivery_days:7,valid_until:today(),note:'',items:data.value?.items.map(i=>({request_item_id:i.id,unit_price:''}))||[]});quoteDialog.value=true}
async function saveQuote(){if(!canQuote.value)return;if(!quote.supplier_id||!quote.valid_until||quote.delivery_days<0||quote.items.some(i=>String(i.unit_price).trim()===''||!Number.isFinite(Number(i.unit_price))||Number(i.unit_price)<0)){ElMessage.warning('请完整填写供应商、有效期及各材料报价');return}if(await run(()=>post(`/requests/${route.params.id}/quotes`,quote),'供应商报价已记录'))quoteDialog.value=false}
function quotePrice(q:Row,item:Row){return q.items?.find((r:Row)=>String(r.request_item_id)===String(item.id))?.unit_price}
async function submit(){if(await confirmAction('确认提交采购申请？提交后将进入审批流程。'))await run(()=>post(`/requests/${route.params.id}/submit`),'申请已提交')}
async function approve(){if(!approval.comment.trim()&&approval.decision==='REJECTED'){ElMessage.warning('请填写驳回原因');return}if(await run(()=>post(`/requests/${route.params.id}/approve`,approval),'审批已记录'))approvalDialog.value=false}
async function createOrder(){if(!canAward.value)return;if(!award.quote_id||!award.reason.trim()){ElMessage.warning('请选择中选报价并填写中选原因');return}let created:Row|undefined;if(await run(async()=>{created=await post<Row>(`/requests/${route.params.id}/orders`,award)},'采购订单已生成')){awardDialog.value=false;if(created&&auth.can('order:read')&&auth.hasMenu('orders'))router.push(`/orders/${created.id}`)}}
const isMobile=useMediaQuery()
watch(()=>route.query.tab,v=>{tab.value=String(v||'items')})
</script>
<template><PageHeader :title="data?.code||'采购申请详情'" subtitle="材料需求、采购审批与供应商比价，一单贯通。" back="/requests"><el-button :loading="loading" @click="load">刷新</el-button><el-button v-if="canEdit" @click="editor=true">编辑草稿</el-button><el-button v-if="canEdit" type="primary" :loading="saving" @click="submit">提交审批</el-button><el-button v-if="canApprove" type="primary" @click="approvalDialog=true">处理审批</el-button></PageHeader><ResourceState :loading="loading" :error="error" @retry="load"><template v-if="data"><el-alert v-if="data.source_order_id" type="info" :closable="false" class="mb"><template #title>补采来源：{{data.source_order_code}} · 本申请需要独立审批。<el-button v-if="auth.can('order:read')&&auth.hasMenu('orders')" link type="primary" @click="$router.push(`/orders/${data.source_order_id}`)">查看原订单</el-button></template></el-alert><div class="detail-banner"><div><StatusTag :value="data.status"/><h2>{{data.project_name}}</h2><p>申请人 {{data.applicant_name}} · 要求到货 {{data.required_date}}</p></div><div><span class="muted">申请总金额（元）</span><strong>{{money(data.total_amount)}}</strong><small>金额由服务端计算</small></div></div><section class="panel"><el-descriptions :column="isMobile?1:3"><el-descriptions-item label="申请单号">{{data.code}}</el-descriptions-item><el-descriptions-item label="创建时间">{{dateTime(data.created_at)}}</el-descriptions-item><el-descriptions-item label="材料种类">{{data.items.length}}</el-descriptions-item><el-descriptions-item label="申请说明" :span="isMobile?1:3">{{data.note||'—'}}</el-descriptions-item></el-descriptions><el-tabs v-model="tab"><el-tab-pane label="需求材料" name="items"><DataTable :rows="data.items" :search="false" :columns="[{key:'material_name',label:'材料名称'},{key:'specification',label:'规格型号'},{key:'unit',label:'单位',width:70},{key:'quantity',label:'申请数量',number:true},{key:'unit_price',label:'预估单价（元）',money:true},{key:'amount',label:'金额（元）',money:true}]"/></el-tab-pane><el-tab-pane v-if="auth.can('quote:read')" :label="`询价与比价（${quoteList.paging.total}）`" name="quotes"><div class="subheading"><div><h3>材料逐项报价对比</h3><p class="muted">整单中选，报价一经下单锁定。至少记录两家供应商后比较并选择。</p></div><div><el-button v-if="canQuote" type="primary" plain @click="newQuote">＋ 录入报价</el-button><el-button v-if="canAward" type="primary" :disabled="Number(data?.quote_supplier_count||0)<2" @click="awardDialog=true">选择中选并下单</el-button></div></div><el-alert v-if="hasOrder" title="该申请已生成采购订单，报价及中选结果已锁定。" type="success" :closable="false" show-icon class="mb"/><el-alert v-if="!hasOrder&&Number(data?.quote_supplier_count||0)<2" title="请录入至少两家供应商报价，完成逐项比较后下单。" type="info" :closable="false" show-icon class="mb"/><ResourceState :loading="quoteList.loading.value" :error="quoteList.error.value" @retry="quoteList.load"><div class="table-footer"><span class="muted">本页 {{quotes.length}} 份报价，共 {{quoteList.paging.total}} 份；翻页比较</span><el-pagination v-model:current-page="quoteList.paging.page" :page-size="20" :total="quoteList.paging.total" layout="prev, pager, next" :pager-count="5"/></div></ResourceState><p class="mobile-comparison-hint">左右滑动表格，对比各供应商逐项报价。</p><el-table :data="data.items" border empty-text="暂无材料"><el-table-column prop="material_name" label="材料名称" min-width="180"/><el-table-column prop="specification" label="规格 / 型号" min-width="120"/><el-table-column label="需求数量" width="130"><template #default="{row}">{{number(row.quantity)}} {{row.unit}}</template></el-table-column><el-table-column v-for="q in quotes" :key="q.id" :label="q.supplier_name||`供应商 #${q.supplier_id}`" min-width="180" align="right"><template #header><div class="quote-column"><b>{{q.supplier_name||`供应商 #${q.supplier_id}`}}</b><small>交期 {{q.delivery_days}} 天 · 单价（元）</small></div></template><template #default="{row}"><span class="numeric">{{money(quotePrice(q,row))}}</span></template></el-table-column></el-table><div class="quote-cards"><article v-for="q in quotes" :key="q.id"><h4>{{q.supplier_name}}</h4><p>报价总额 <strong>¥ {{money(q.total_amount)}}</strong></p><p>有效至 {{q.valid_until}} · 交货 {{q.delivery_days}} 天</p><p class="muted">{{q.note||'未填写补充说明'}}</p></article></div></el-tab-pane><el-tab-pane label="审批记录" name="approvals"><RelatedRecords entity="request-approvals" :filters="{request_id:route.params.id,id:route.query.approval_id}" :columns="[{key:'decision',label:'审批结论',status:true},{key:'operator_name',label:'操作人'},{key:'comment',label:'意见'},{key:'created_at',label:'时间',date:true}]"/></el-tab-pane><el-tab-pane label="全链路追溯" name="trace"><TracePanel v-if="tab==='trace'" kind="requests" :id="String(route.params.id)"/></el-tab-pane></el-tabs></section></template></ResourceState><RequestEditor v-model="editor" :record="data||undefined" @saved="reload"/><el-dialog v-if="!hasOrder" v-model="quoteDialog" title="录入供应商报价" width="850px" :close-on-click-modal="false"><el-form label-position="top"><div class="form-grid"><el-form-item label="供应商 *"><RecordSelect v-model="quote.supplier_id" entity="suppliers" :filters="{status:'ACTIVE'}"/></el-form-item><el-form-item label="交货天数 *"><el-input-number v-model="quote.delivery_days" :min="0" :precision="0"/></el-form-item><el-form-item label="报价有效期 *"><el-date-picker v-model="quote.valid_until" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="报价备注"><el-input v-model="quote.note"/></el-form-item></div><div v-if="isMobile" class="mobile-form-lines"><section v-for="(row,index) in quote.items" :key="row.request_item_id" class="mobile-form-line"><h3>{{index+1}} · {{data?.items.find(i=>i.id===row.request_item_id)?.material_name}}</h3><p class="field-hint">{{data?.items.find(i=>i.id===row.request_item_id)?.specification}}</p><el-form-item label="含税单价（元）"><el-input v-model="row.unit_price" inputmode="decimal" placeholder="请输入单价"/></el-form-item></section></div><el-table v-else :data="quote.items" border><el-table-column label="材料名称"><template #default="{row}">{{data?.items.find(i=>i.id===row.request_item_id)?.material_name}}</template></el-table-column><el-table-column label="规格型号"><template #default="{row}">{{data?.items.find(i=>i.id===row.request_item_id)?.specification}}</template></el-table-column><el-table-column label="含税单价（元）"><template #default="{row}"><el-input v-model="row.unit_price" inputmode="decimal" placeholder="请输入单价"/></template></el-table-column></el-table></el-form><template #footer><el-button @click="quoteDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveQuote">保存报价</el-button></template></el-dialog><el-dialog v-if="!hasOrder" v-model="awardDialog" title="确认中选与采购下单" width="600px" :close-on-click-modal="false"><el-alert title="按整份申请下单，材料数量以已审批申请为准。" :closable="false" type="info" show-icon class="mb"/><el-form label-position="top"><el-form-item label="中选供应商 *"><el-select v-model="award.quote_id"><el-option v-for="q in quotes" :key="q.id" :label="`${q.supplier_name} · ¥ ${money(q.total_amount)}`" :value="q.id"/></el-select></el-form-item><el-form-item label="中选原因 *"><el-input v-model="award.reason" type="textarea" :rows="4" maxlength="1000" show-word-limit placeholder="综合说明价格、交期、质量及资质等中选依据"/></el-form-item></el-form><template #footer><el-button @click="awardDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="createOrder">确认并生成订单</el-button></template></el-dialog><el-dialog v-model="approvalDialog" title="采购申请审批" width="550px"><el-form label-position="top"><el-form-item label="审批结果"><el-radio-group v-model="approval.decision"><el-radio-button value="APPROVED">批准</el-radio-button><el-radio-button value="REJECTED">驳回</el-radio-button></el-radio-group></el-form-item><el-form-item label="审批意见"><el-input v-model="approval.comment" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="approvalDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="approve">提交审批结果</el-button></template></el-dialog></template>
